yakit.AutoInitYakit()

# Input your code!

mtu := cli.Int("mtu", cli.setVerboseName("最大传输单元"),cli.setDefault(1500))
target := cli.String("target",cli.setVerboseName("联通性检测目标网站"),cli.setDefault("https://yaklang.com"),cli.setHelp("目标的 url"))

cli.check()

urlIns,err := str.ParseStringUrlToUrlInstance(target)
if err != nil {
    yakit.StatusCard("联通性检测未通过", sprintf("目标 %s 解析url失败", target))
    return
}

iplist := []
if !str.IsIPv4(urlIns.Host) {
    iplist = os.LookupIP(target)
}else {
    iplist = [urlIns.Host]
}

if len(iplist) == 0 {
    yakit.StatusCard("联通性检测未通过", sprintf("目标 %s 未解析出ip地址", target))
    return
}




ctx, cancel := context.WithCancel(context.Background())
defer cancel()

device,err := netstack.CreatePrivilegedDeviceWithMTU(mtu)
if err != nil {
    yakit.Error("启动 tun 设备失败 %v",err)
    yakit.StatusCard("联通性检测未通过", "启动 tun 设备失败")
    return
}


tunName,err := device.Name()
if err != nil {
    yakit.Error("获取 tun 设备名失败 %v",err)
    yakit.StatusCard("联通性检测未通过", "获取 tun 设备名失败")
    return
}

yakit.StatusCard("tun设备创建检测", "通过✅")


yakit.StatusCard("检测设备名", tunName)
defer device.Close()
vm,err := netstack.NewVMFromDeviceWithContext(ctx,device)
if err != nil {
    yakit.Error("启动 netstack 虚拟机失败 %v",err)
    yakit.StatusCard("联通性检测未通过", "启动 netstack 虚拟机失败")
    return
}

yakit.StatusCard("虚拟机创建检测", "通过✅")
defer vm.Close()


manager,err := netstack.GetPrivilegedSystemRouteManager()
if err != nil {
    yakit.Error("启动特权路由管理器失败 %v",err)
    yakit.StatusCard("联通性检测未通过", "启动路由管理器失败")
    return
}
defer manager.Close()


err := manager.AddIPRoute(iplist, tunName )
if err != nil {
    yakit.Error("添加测试目标劫持路由失败 %v",err)
    yakit.StatusCard("联通性检测未通过", "添加测试目标劫持路由失败")
    return
}


success := false
records := manager.GetExistedManagedSystemTableRoute()
allAddr := []string{}
for i in records {
    allAddr = append(allAddr, i.IPAddr)
}
if !str.StringSliceContainsAll(allAddr, iplist...) {
    yakit.Error("校验添加路由表失败")
    yakit.StatusCard("联通性检测未通过", "校验添加路由表未通过")
    return
}
yakit.StatusCard("路由管理器可用检测", "通过✅")


sig := make(chan bool, 2)

go func() {
    vm.StartForwardingCallbackMode(func(conn){
        loaclAddr := conn.LocalAddr()
        host,_,err := str.ParseStringToHostPort(loaclAddr.String())
        if err != nil {
            yakit.Error("获取 host 失败 %v", err)
        }
        yakit.Info("tunnel Hijack [%s] -> [%s]", conn.RemoteAddr(), conn.LocalAddr())
        if str.StringSliceContains(iplist, host) {
            sig <- true
        }
    })
}()

go func() {
    time.sleep(5)
    sig <- false
}()

poc.Get(target,poc.connectTimeout(2))

ok := <- sig

err := manager.DeleteRoutesForInterface(tunName)
if err != nil {
    yakit.Error("删除测试目标劫持路由失败 %v",err)
    yakit.StatusCard("警告", "删除测试目标劫持路由失败")
}


if !ok {
    yakit.StatusCard("转发连接检测", "失败❌")
    return
}else {
    yakit.StatusCard("转发连接检测", "通过✅")
    return
}
